#!/usr/bin/env python3
"""Small pinned Java 1.20.4 recipe/icon corpus. Original Mojang data is not MIT."""
import base64, concurrent.futures, hashlib, json, subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
REF='90d256dfee7b6fd8014e1bc3b107e64a530c5f9b'
REPO='InventivetalentDev/minecraft-assets'
OUT=ROOT/'.harness/fixtures/java-refinements-1.20.4'
ICONS={'golden_pickaxe':600,'golden_axe':601,'golden_shovel':602,'golden_sword':603,'golden_hoe':604,'iron_nugget':605,'gold_nugget':606,'copper_ingot':607,'amethyst_shard':608,'brick':609,'clay_ball':610,'red_dye':611,'yellow_dye':612,'green_dye':613,'blue_dye':614,'black_dye':615}
RECIPES=list(ICONS.keys())[:7]+['iron_ingot_from_nuggets','gold_ingot_from_nuggets','spyglass','lantern','fishing_rod','stone_bricks','sandstone','white_wool_from_string','lever','observer','red_bed','bricks','red_dye_from_poppy','yellow_dye_from_dandelion','blue_dye','honey_block','honey_bottle','oak_boat']
paths=['assets/minecraft/textures/item/'+n+'.png' for n in ICONS]+['data/minecraft/recipes/'+n+'.json' for n in RECIPES]+['assets/minecraft/textures/entity/bed/red.png']
def fetch(path):
 cache=ROOT/'.cache/java-refinements'/REF/path
 if not cache.exists():
  obj=json.loads(subprocess.check_output(['gh','api',f'repos/{REPO}/contents/{path}?ref={REF}']))
  cache.parent.mkdir(parents=True,exist_ok=True);cache.write_bytes(base64.b64decode(obj['content']))
 raw=cache.read_bytes();target=OUT/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(raw)
 return {'path':path,'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
with concurrent.futures.ThreadPoolExecutor(max_workers=5) as pool: files=list(pool.map(fetch,paths))
(OUT/'manifest.json').write_text(json.dumps({'version':'1.20.4','repository':REPO,'commit':REF,'files':files},indent=2)+'\n')
art={str(i):base64.b64encode((OUT/f'assets/minecraft/textures/item/{n}.png').read_bytes()).decode() for n,i in ICONS.items()}
(ROOT/'src/game/art/javaRefinements.generated.ts').write_text('// Generated by scripts/sync-java-refinements.py. Java 1.20.4 '+REF+'\n// Original Mojang/Microsoft artwork, NOT project MIT.\nexport const JAVA_REFINEMENT_ICONS: Record<number,string> = '+json.dumps(art,indent=2)+';\nexport const JAVA_BED_TEXTURE = '+json.dumps(base64.b64encode((OUT/'assets/minecraft/textures/entity/bed/red.png').read_bytes()).decode())+';\n')
print(f'Pinned {len(files)} native files.')

recipes={n:json.loads((OUT/f'data/minecraft/recipes/{n}.json').read_text()) for n in RECIPES}
(ROOT/'src/game/art/javaRecipes.generated.ts').write_text('// Generated by scripts/sync-java-refinements.py. Pinned Java 1.20.4 data, NOT project MIT.\nexport const JAVA_REFINEMENT_RECIPES: Record<string,any> = '+json.dumps(recipes,indent=2)+';\n')
